package com.manticore.serviceimport com.manticore.dto.TaskCreateDtoimport com.manticore.dto.TaskFilterDtoimport com.manticore.dto.TaskStatusHistoryViewDtoimport com.manticore.dto.TaskViewDtoimport com.manticore.exception.StorageExceptionimport com.manticore.mapper.TaskMapperimport com.manticore.model.Taskimport com.manticore.model.TaskStatusimport com.manticore.repository.TaskRepositoryimport com.manticore.repository.TaskSpecificationBuilderimport com.manticore.repository.TaskStatusHistoryRepositoryimport com.manticore.service.storage.FileStorageServiceimport io.github.oshai.kotlinlogging.KotlinLoggingimport org.springframework.beans.factory.annotation.Valueimport org.springframework.data.domain.Pageimport org.springframework.data.domain.Pageableimport org.springframework.stereotype.Serviceimport org.springframework.transaction.annotation.Transactionalimport java.time.LocalDateTimeprivate val log = KotlinLogging.logger {}/** * Реализация сервиса для управления задачами. * * Обрабатывает бизнес-логику создания, получения, обработки и отмены задач. * Использует репозиторий для доступа к БД, маппер для преобразования DTO и сущностей, * и сервис хранилища для проверки файлов в MinIO. * * @author Linempy * @since 15.05.2026 */@Serviceclass TaskServiceImpl(    private val repository: TaskRepository,    private val historyRepository: TaskStatusHistoryRepository,    private val historyRecorder: TaskStatusHistoryRecorder,    private val mapper: TaskMapper,    private val storage: FileStorageService,    private val taskWorker: TaskProcessor,    @Value("\${services.s3.bucketName}")    private var bucketName: String? = null,    ) : TaskService {    @Transactional    override fun createTask(createDto: TaskCreateDto): TaskViewDto? {        checkExistFileInStorage(createDto.fileKey)        val task: Task = mapper.toEntity(createDto)        task.status = TaskStatus.PENDING        val savedTask: Task = repository.save(task)        historyRecorder.recordTransition(savedTask.id!!, null, TaskStatus.PENDING, "API")        return mapper.toDto(savedTask)    }    @Transactional    override fun startProcessing(id: Long): TaskViewDto? {        val task = repository.findById(id).orElseThrow {            NoSuchElementException("Task $id not found")        }        if (task.status !in listOf(TaskStatus.FAILED, TaskStatus.CANCELLED)) {            throw IllegalStateException("Cannot restart task in status ${task.status}")        }        val previousStatus = task.status!!        task.status = TaskStatus.PENDING        task.isCancel = false        task.errorMessage = null        task.result = null        task.completedAt = null        val saved = repository.save(task)        historyRecorder.recordTransition(saved.id!!, previousStatus, TaskStatus.PENDING, "API")        taskWorker.processTask(saved.id!!)        return mapper.toDto(saved)    }    override fun getTask(id: Long): TaskViewDto? {        val task: Task = repository.getReferenceById(id)        return mapper.toDto(task)    }    override fun getTasks(        filterDto: TaskFilterDto,        pageable: Pageable,        ): Page<TaskViewDto> {        val specification = TaskSpecificationBuilder.buildSpecification(filterDto)        val tasks: Page<Task> = repository.findAll(specification, pageable)        return tasks.map(mapper::toDto)    }    @Transactional(readOnly = true)    override fun getTaskStatusHistory(taskId: Long): List<TaskStatusHistoryViewDto> {        if (!repository.existsById(taskId)) {            throw NoSuchElementException("Task $taskId not found")        }        return historyRepository.findByTaskIdOrderByChangedAtAsc(taskId).map { h ->            TaskStatusHistoryViewDto(                id = h.id!!,                taskId = h.taskId,                oldStatus = h.oldStatus,                newStatus = h.newStatus,                changedAt = h.changedAt,                changedBy = h.changedBy,                metadata = h.metadata,                )        }    }    @Transactional    override fun cancelTask(id: Long): TaskViewDto {        val task = repository.findById(id).orElseThrow {            NoSuchElementException("Task $id not found")        }        if (task.status !in listOf(TaskStatus.PENDING, TaskStatus.PROCESSING)) {            throw IllegalStateException("Cannot cancel task in status ${task.status}")        }        val previousStatus = task.status!!        task.status = TaskStatus.CANCELLED        task.isCancel = true        task.completedAt = LocalDateTime.now()        val saved = repository.save(task)        historyRecorder.recordTransition(saved.id!!, previousStatus, TaskStatus.CANCELLED, "API")        return mapper.toDto(saved)    }    private fun checkExistFileInStorage(fileKey: String) {        try {            storage.download(bucketName, fileKey)        } catch (e: StorageException) {            log.error(e) { "Ошибка получения файла из хранилища для ключа fileKey: $fileKey" }            throw IllegalArgumentException("File with key '$fileKey' does not exist in storage")        }    }}